package io.reimu.core;

import java.nio.file.*;
import java.util.*;
import static io.reimu.core.Data.*;
import static io.reimu.core.Domain.*;

/** Real offline tests of production core sources. No SDK, HTTP or browser claims. */
public final class CoreSpec {
    private static int passed;
    @FunctionalInterface interface Test { void run() throws Exception; }
    static void test(String name,Test action) throws Exception { action.run();passed++;System.out.println("PASS "+name); }
    static void eq(Object a,Object b){if(!Objects.equals(a,b))throw new AssertionError(a+" != "+b);}
    static void ok(boolean b){if(!b)throw new AssertionError("condition failed");}
    static void fault(String code,Runnable r){try{r.run();throw new AssertionError("Expected "+code);}catch(Fault f){eq(code,f.code);}}
    static final Identity ALICE=new Identity("local","main","alice",true),BOB=new Identity("local","main","bob",false);
    static final class Fixture implements AutoCloseable {
        final Path dir=Files.createTempDirectory("reimu-spec-");final Path file=dir.resolve("state.bin");
        FileStore store=new FileStore(file);Workspace w=new Workspace(store);Execution x=new Execution(w);TableQueries tables=new TableQueries(store);final String ref;
        Fixture() throws Exception { Agent a=new Agent();a.name="测试助手";a.systemPrompt="基于证据回答";a.tools=new ArrayList<>(ToolRegistry.names());a=w.saveAgent(ALICE,a,0);a=w.publish(ALICE,a.id,a.entityVersion);ref=a.id+"@"+a.revision; }
        String conversation(){return (String)w.create(ALICE,id(),ref,"验收会话").get("id");}
        String send(String cid,String text){return (String)x.send(ALICE,cid,id(),text,List.of()).get("runId");}
        AgentRunner.Input pending(String cid,String q){send(cid,q);return x.claim().orElseThrow();}
        void slice(AgentRunner.Input i) throws Exception {x.commit(i,new DemoRunner().advance(i,d->x.delta(i,d)));}
        void drain() throws Exception {for(int n=0;n<40;n++){var op=x.claimOperation();if(op.isPresent()){x.executeLocal(op.get().id);continue;}var i=x.claim();if(i.isPresent()){slice(i.get());continue;}return;}throw new AssertionError("loop limit");}
        Operation operation(){return store.read(s->s.operations.values().stream().findFirst().orElseThrow());}
        String artifact(String kind){return store.read(s->s.artifacts.values().stream().filter(a->a.kind.equals(kind)).findFirst().orElseThrow().id);}
        void reopen() throws Exception {store.close();store=new FileStore(file);w=new Workspace(store);x=new Execution(w);tables=new TableQueries(store);}
        @Override public void close() throws java.io.IOException {store.close();try(var p=Files.walk(dir)){for(Path f:p.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(f);}}
    }
    public static void main(String[] argv)throws Exception {
        passed=0;
        test("canonical hash ignores map ordering",()->eq(hash(map("a",1,"b",List.of("中😀"))),hash(map("b",List.of("中😀"),"a",1))));
        test("transaction rollback and defensive copies",()->{try(var f=new Fixture()){int size=f.store.read(s->s.agents.size());try{f.store.write(s->{s.agents.clear();throw new IllegalStateException("abort");});}catch(IllegalStateException e){}eq(size,f.store.read(s->s.agents.size()));f.store.read(s->{s.agents.clear();return null;});eq(size,f.store.read(s->s.agents.size()));}});
        test("local single-worker lock rejects a second writer",()->{try(var f=new Fixture()){try(var other=new FileStore(f.file)){throw new AssertionError("second writer accepted");}catch(java.nio.channels.OverlappingFileLockException|java.io.IOException expected){}}});
        test("conversation creation is idempotent",()->{try(var f=new Fixture()){String key=id();var a=f.w.create(ALICE,key,f.ref,"测试");eq(a,f.w.create(ALICE,key,f.ref,"测试"));eq(1,f.store.read(s->s.conversations.size()));fault("IDEMPOTENCY_CONFLICT",()->f.w.create(ALICE,key,f.ref,"另一个"));}});
        test("send idempotency and receipt recovery",()->{try(var f=new Fixture()){String cid=f.conversation(),key=id();var a=f.x.send(ALICE,cid,key,"你好",List.of());eq(a,f.x.send(ALICE,cid,key,"你好",List.of()));eq(a,f.w.receipt(ALICE,key));eq(2,list(f.w.snapshot(ALICE,cid).get("messages")).size());fault("IDEMPOTENCY_CONFLICT",()->f.x.send(ALICE,cid,key,"改变",List.of()));}});
        test("ownership isolation including another administrator",()->{try(var f=new Fixture()){String cid=f.conversation();fault("RESOURCE_NOT_AVAILABLE",()->f.w.snapshot(BOB,cid));fault("RESOURCE_NOT_AVAILABLE",()->f.w.snapshot(new Identity("local","main","bob",true),cid));fault("FORBIDDEN",()->f.w.saveAgent(BOB,new Agent(),0));}});
        test("optimistic conversation changes and archive persistence",()->{try(var f=new Fixture()){String cid=f.conversation();f.w.edit(ALICE,cid,1,"新标题",true,true);fault("VERSION_CONFLICT",()->f.w.edit(ALICE,cid,1,"覆盖",null,null));fault("ARCHIVED",()->f.send(cid,"你好"));f.reopen();eq("新标题",object(f.w.snapshot(ALICE,cid).get("conversation")).get("title"));}});
        test("published agent version immutable",()->{try(var f=new Fixture()){Agent draft=f.w.agents(ALICE).get(0);draft.systemPrompt="changed";f.w.saveAgent(ALICE,draft,draft.entityVersion);eq("基于证据回答",f.store.read(s->s.agentVersions.get(f.ref).systemPrompt));}});
        test("one active run per conversation",()->{try(var f=new Fixture()){String cid=f.conversation();f.send(cid,"你好");fault("RUN_ACTIVE",()->f.send(cid,"重复任务"));fault("RUN_ACTIVE",()->f.w.delete(ALICE,cid));}});
        test("multi-turn checkpoint persists after reopening",()->{try(var f=new Fixture()){String cid=f.conversation();f.send(cid,"第一条");f.drain();f.reopen();f.send(cid,"上一条是什么");f.drain();var state=f.store.read(s->s.conversations.get(cid));ok(canonical(state.messages.get(3).parts).contains("第一条"));}});
        test("snapshot watermark and event chain",()->{try(var f=new Fixture()){String cid=f.conversation();var snap=f.w.snapshot(ALICE,cid);f.send(cid,"你好");var es=f.w.events(ALICE,cid,(String)snap.get("streamId"),(String)snap.get("cursor"));ok(es.size()>1);String previous=(String)snap.get("cursor");for(var e:es){eq(previous,e.previousCursor());previous=e.cursor();}eq(f.w.snapshot(ALICE,cid).get("cursor"),previous);}});
        test("old event payloads are immutable",()->{try(var f=new Fixture()){String cid=f.conversation();f.send(cid,"你好");String old=f.store.read(s->canonical(s.conversations.get(cid).events.get(1).data()));f.drain();eq(old,f.store.read(s->canonical(s.conversations.get(cid).events.get(1).data())));}});
        test("expired or wrong stream cursor rejected",()->{try(var f=new Fixture()){String cid=f.conversation();fault("CURSOR_EXPIRED",()->f.w.events(ALICE,cid,"wrong","p0"));fault("CURSOR_EXPIRED",()->f.w.events(ALICE,cid,"s-"+cid+"-1","pffff"));}});
        test("UTF16 Chinese and emoji offsets",()->{try(var f=new Fixture()){String cid=f.conversation();var i=f.pending(cid,"测试");f.x.delta(i,"中😀");f.x.delta(i,"文");var ev=f.store.read(s->s.conversations.get(cid).events.stream().filter(e->e.type().equals("message.text.delta")).toList());eq(3,ev.get(1).data().get("offsetUtf16"));}});
        test("tool intent commits before effects",()->{try(var f=new Fixture()){String cid=f.conversation();var i=f.pending(cid,"生成演示流程");f.slice(i);eq(0,f.store.read(s->s.artifacts.size()));eq(4,f.store.read(s->s.operations.size()));ok(!f.store.read(s->s.conversations.get(cid).checkpoint).isBlank());f.reopen();f.drain();eq(4,f.store.read(s->s.artifacts.size()));}});
        test("four artifact types generated by durable gateway",()->{try(var f=new Fixture()){String cid=f.conversation();f.send(cid,"演示");f.drain();eq(Set.of("reactflow","table","markdown","webpage"),f.store.read(s->new HashSet<>(s.artifacts.values().stream().map(a->a.kind).toList())));eq("idle",object(f.w.snapshot(ALICE,cid).get("activity")).get("state"));}});
        test("invalid tool rolls back checkpoint and effects",()->{try(var f=new Fixture()){String cid=f.conversation();var i=f.pending(cid,"你好");fault("TOOL_DENIED",()->f.x.commit(i,new AgentRunner.Outcome("bad","",List.of(new AgentRunner.ToolCall(id(),"shell",map())),false)));eq("",f.store.read(s->s.conversations.get(cid).checkpoint));eq(0,f.store.read(s->s.operations.size()));}});
        test("approval required before internal ticket exists",()->{try(var f=new Fixture()){String cid=f.conversation();f.send(cid,"创建工单");f.drain();ok(f.x.claimOperation().isEmpty());eq(0,f.store.read(s->s.tickets.size()));eq("approval_pending",f.operation().state);}});
        test("approval binds exact operation hash and revision",()->{try(var f=new Fixture()){String cid=f.conversation();f.send(cid,"工单");f.drain();var o=f.operation();fault("APPROVAL_CONFLICT",()->f.x.decide(ALICE,o.approvalId,o.entityVersion,o.id,"wrong","approved",id()));fault("RESOURCE_NOT_AVAILABLE",()->f.x.decide(BOB,o.approvalId,o.entityVersion,o.id,o.argsHash,"approved",id()));eq(0,f.store.read(s->s.tickets.size()));}});
        test("approved operation executes once after reopen",()->{try(var f=new Fixture()){String cid=f.conversation();f.send(cid,"工单");f.drain();var o=f.operation();String key=id();var a=f.x.decide(ALICE,o.approvalId,o.entityVersion,o.id,o.argsHash,"approved",key);eq(a,f.x.decide(ALICE,o.approvalId,o.entityVersion,o.id,o.argsHash,"approved",key));f.reopen();f.drain();eq(1,f.store.read(s->s.tickets.size()));f.drain();eq(1,f.store.read(s->s.tickets.size()));}});
        test("rejected approval does not execute ticket",()->{try(var f=new Fixture()){String cid=f.conversation();f.send(cid,"工单");f.drain();var o=f.operation();f.x.decide(ALICE,o.approvalId,o.entityVersion,o.id,o.argsHash,"rejected",id());f.drain();eq(0,f.store.read(s->s.tickets.size()));eq("failed",f.operation().state);}});
        test("expired approval fails closed",()->{try(var f=new Fixture()){String cid=f.conversation();f.send(cid,"工单");f.drain();var o=f.operation();f.store.write(s->{s.operations.get(o.id).expiresAt="2000-01-01T00:00:00Z";return null;});fault("APPROVAL_EXPIRED",()->f.x.decide(ALICE,o.approvalId,o.entityVersion,o.id,o.argsHash,"approved",id()));}});
        test("question answer uses durable question id and dedupes",()->{try(var f=new Fixture()){String cid=f.conversation();f.send(cid,"请补问");f.drain();var q=f.store.read(s->s.questions.values().iterator().next());String key=id();var a=f.x.answer(ALICE,q.id,q.entityVersion,"生产环境",key);eq(a,f.x.answer(ALICE,q.id,q.entityVersion,"生产环境",key));f.reopen();f.drain();eq(3,f.store.read(s->s.conversations.get(cid).messages.size()));}});
        test("cancel pending approval revokes without side effects",()->{try(var f=new Fixture()){String cid=f.conversation(),rid=f.send(cid,"工单");f.drain();f.x.cancel(ALICE,rid,id());eq("revoked",f.operation().decision);ok(f.x.claimOperation().isEmpty());eq("cancelled",f.store.read(s->s.runs.get(rid).state));}});
        test("cancel running model waits for confirmation",()->{try(var f=new Fixture()){String cid=f.conversation();var i=f.pending(cid,"你好");f.x.cancel(ALICE,i.runId(),id());eq("cancelling",f.store.read(s->s.runs.get(i.runId()).state));f.x.failed(i,"CANCELLED");eq("cancelled",f.store.read(s->s.runs.get(i.runId()).state));}});
        test("restart completes cancellation of stopped model",()->{try(var f=new Fixture()){String cid=f.conversation();var i=f.pending(cid,"你好");f.x.cancel(ALICE,i.runId(),id());f.reopen();f.x.recover();eq("cancelled",f.store.read(s->s.runs.get(i.runId()).state));}});
        test("stale worker cannot overwrite recovered execution",()->{try(var f=new Fixture()){String cid=f.conversation();var i=f.pending(cid,"你好");f.x.recover();fault("STALE_EXECUTION",()->f.x.commit(i,new AgentRunner.Outcome("bad","bad",List.of(),true)));f.drain();eq("completed",f.store.read(s->s.runs.get(i.runId()).state));}});
        test("unknown external effects are never blindly replayed",()->{try(var f=new Fixture()){String cid=f.conversation();f.send(cid,"工单");f.drain();var o=f.operation();f.x.decide(ALICE,o.approvalId,o.entityVersion,o.id,o.argsHash,"approved",id());f.x.claimOperation().orElseThrow();f.reopen();f.x.recover();eq("unknown",f.operation().state);ok(f.x.claimOperation().isEmpty());eq("needs_attention",f.store.read(s->s.runs.get(o.runId).state));}});
        test("private knowledge checked before retrieval",()->{try(var f=new Fixture()){var r=f.w.putResource(ALICE,"knowledge","运维手册","GPU 利用率低需要采集批大小与队列指标。",List.of());ok(!f.w.knowledge(ALICE,List.of(r.id+"@1"),"GPU").isEmpty());fault("RESOURCE_NOT_AVAILABLE",()->f.w.knowledge(BOB,List.of(r.id+"@1"),"GPU"));}});
        test("skill manifest and explicit sharing",()->{try(var f=new Fixture()){fault("SKILL_MANIFEST",()->f.w.putResource(ALICE,"skill","错","无元信息",List.of()));var r=f.w.putResource(ALICE,"skill","诊断","---\nname: diagnosis\ndescription: 诊断\n---\n只使用已授权工具",List.of("bob"));eq(r.id,f.w.resources(BOB,"skill").get(0).id);}});
        test("memory candidate confirmation and withdrawal",()->{try(var f=new Fixture()){String cid=f.conversation();f.send(cid,"记住用中文回答");f.drain();var m=f.w.memories(ALICE).get(0);eq("candidate",m.status);eq(0,f.w.memories(BOB).size());m=f.w.decideMemory(ALICE,m.id,m.entityVersion,"active");eq("active",m.status);eq("",f.store.read(s->s.conversations.get(cid).checkpoint));f.w.decideMemory(ALICE,m.id,m.entityVersion,"deleted");eq(0,f.w.memories(ALICE).size());}});
        test("memory cannot be changed under an in-flight context",()->{try(var f=new Fixture()){String cid=f.conversation();f.send(cid,"记住中文");f.drain();var m=f.w.memories(ALICE).get(0);f.send(cid,"你好");fault("RUN_ACTIVE",()->f.w.decideMemory(ALICE,m.id,m.entityVersion,"deleted"));}});
        test("artifact ownership and independent opening",()->{try(var f=new Fixture()){String cid=f.conversation();f.send(cid,"演示");f.drain();String aid=f.artifact("markdown");int n=f.store.read(s->s.runs.size());f.w.artifactView(ALICE,aid,1);f.w.artifactView(ALICE,aid,1);eq(n,f.store.read(s->s.runs.size()));fault("RESOURCE_NOT_AVAILABLE",()->f.w.artifactView(BOB,aid,1));}});
        test("artifact revision is immutable and conflict guarded",()->{try(var f=new Fixture()){String cid=f.conversation();f.send(cid,"演示");f.drain();String aid=f.artifact("markdown");String hash=(String)f.w.artifactView(ALICE,aid,1).get("contentHash");var i=f.pending(cid,"改报告");var args=map("kind","markdown","title","报告","artifactId",aid,"baseRevision",1,"content",map("blocks",List.of(map("blockId","b1","markdown","# 新版本"))));f.x.commit(i,new AgentRunner.Outcome("revision","",List.of(new AgentRunner.ToolCall(id(),"artifact_revise",args)),false));f.drain();eq(hash,f.w.artifactView(ALICE,aid,1).get("contentHash"));eq(2,f.w.artifactView(ALICE,aid,2).get("revision"));var next=f.pending(cid,"再次改");f.x.commit(next,new AgentRunner.Outcome("next","",List.of(new AgentRunner.ToolCall(id(),"artifact_revise",args)),false));var op=f.x.claimOperation().orElseThrow();fault("VERSION_CONFLICT",()->f.x.executeLocal(op.id));eq(2,list(f.w.artifactMeta(ALICE,aid).get("revisions")).size());}});
        test("graph endpoints and URL protocols validated",()->{var graph=map("purpose","explanatory","nodes",List.of(map("id","n1","type","step","label","开始","position",map("x",0,"y",0))),"edges",List.of(map("id","e","source","n1","target","missing")));try{ArtifactRules.validate("reactflow",graph);throw new AssertionError();}catch(Fault expected){}try{ArtifactRules.safeUrl("javascript:alert(1)");throw new AssertionError();}catch(Fault expected){}ArtifactRules.safeUrl("https://example.com/docs");});
        test("selection validates actual IDs and conversation",()->{try(var f=new Fixture()){String cid=f.conversation();f.send(cid,"演示");f.drain();String aid=f.artifact("reactflow");var ref=map("artifactId",aid,"revision",1,"selection",map("type","graph_nodes","nodeIds",List.of("missing")));try{f.x.send(ALICE,cid,id(),"解释",List.of(ref));throw new AssertionError();}catch(Fault expected){}String other=f.conversation();var valid=map("artifactId",aid,"revision",1,"selection",map("type","graph_nodes","nodeIds",List.of("n1")));fault("REFERENCE_SCOPE",()->f.x.send(ALICE,other,id(),"解释",List.of(valid)));}});
        test("table sort preserves integer precision and paginates",()->{try(var f=new Fixture()){String cid=f.conversation();f.send(cid,"表格");f.drain();String aid=f.artifact("table");String q=(String)f.tables.create(ALICE,aid,1,"value",true,"",1).get("queryId");var p=f.tables.rows(ALICE,aid,q,null);eq("9007199254740994",object(object(list(p.get("rows")).get(0)).get("values")).get("value"));eq("2",p.get("totalRows"));var p2=f.tables.rows(ALICE,aid,q,(String)p.get("nextCursor"));eq("9007199254740993",object(object(list(p2.get("rows")).get(0)).get("values")).get("value"));fault("RESOURCE_NOT_AVAILABLE",()->f.tables.rows(BOB,aid,q,null));}});
        test("CSV neutralizes formulas and escapes quotes",()->{eq("\"'=1+1\"",TableQueries.cell("=1+1"));eq("\"a\"\"b\"",TableQueries.cell("a\"b"));});
        test("conversation deletion withdraws artifacts but not explicit memories",()->{try(var f=new Fixture()){String cid=f.conversation();f.send(cid,"演示");f.drain();String aid=f.artifact("markdown");f.w.delete(ALICE,cid);fault("RESOURCE_NOT_AVAILABLE",()->f.w.artifactView(ALICE,aid,1));fault("RESOURCE_NOT_AVAILABLE",()->f.w.snapshot(ALICE,cid));}});
        test("fractional artifact revision is rejected",()->{try(var f=new Fixture()){String cid=f.conversation();f.send(cid,"演示");f.drain();String aid=f.artifact("markdown");fault("REFERENCE_REVISION",()->f.x.send(ALICE,cid,id(),"解释",List.of(map("artifactId",aid,"revision",1.5,"selection",map("type","whole")))));}});
        test("table selection must belong to supplied query snapshot",()->{try(var f=new Fixture()){String cid=f.conversation();f.send(cid,"表格");f.drain();String aid=f.artifact("table");String q=(String)f.tables.create(ALICE,aid,1,"value",false,"指标",50).get("queryId");fault("REFERENCE_SELECTION",()->f.x.send(ALICE,cid,id(),"解释",List.of(map("artifactId",aid,"revision",1,"selection",map("type","table_rows","rowIds",List.of("r2"),"querySnapshotId",q)))));}});
        System.out.println("RESULT: "+passed+" cases passed; runtime="+System.getProperty("java.version")+"; compiled with --release 17");
    }
}
